import{_ as s,l as i,o as e,c as l,v as t,p as n,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"负载均衡策略","description":"","frontmatter":{"title":"负载均衡策略","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lb-strategies.md","filePath":"cs/lb-strategies.md","lastUpdated":1789023840000}'),h={name:"cs/lb-strategies.md"};function _(E,a,B,m,A,f){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="负载均衡策略" tabindex="-1">负载均衡策略 <a class="header-anchor" href="#负载均衡策略" aria-label="Permalink to &quot;负载均衡策略&quot;">​</a></h1><div class="epigraph"><p>把请求分到实例上。随机与轮询不管队列；最少连接与 P2C 看忙闲。均衡的是负载，不是一致性档。</p><footer>—— 据 Mitzenmacher, The Power of Two Choices；Dean and Barroso 对选择与排队的讨论整理</footer></div><p>上一课<a href="/cs/tail-latency-hedging">对冲</a>要挑「另一副本」。缺口是<strong>第一次挑选</strong>的策略：轮询、随机、一致性哈希、最少连接、两随机取短者（P2C）。本课钉这些策略与缓存亲和的冲突。通信与可靠课序在此封口，下一课序从追踪开始。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无状态服务：随机/轮询简单，在实例异构或长请求时会把某人队列打长。P2C：随机看两个，去队列更短的，Mitzenmacher 证明在许多模型下指数改善最长队列。有状态：一致性哈希粘滞会话与缓存命中，接<a href="/cs/session-guarantees">会话保证</a>与缓存；实例增减要虚节点，数据结构课已有哈希环。</p><p>缺口：LB 把请求打到落后从库，线性一致掉档——策略必须读规格，不只读 CPU。健康检查是<a href="/cs/failure-detectors">故障检测器</a>的边缘实现，误摘机会放大剩余者负载。</p><p><span class="marginnote">Power of two choices：Azar、Broder、Karlin、Upfal 与 Mitzenmacher 的球箱模型。数据中心 LB 是其工程投影。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>L4 vs L7：L7 能按路径与头选池。加权：按规格容量。连接数 ≠ 队列深度，长轮询会骗最少连接。对冲的第二份应避开第一份的实例，且避开不健康池。</p>',9)),(e(),n(p,null,{default:r(()=>[c(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20ALG%5B%22%E9%9A%8F%E6%9C%BA%20%2F%20RR%20%2F%20P2C%20%2F%20%E5%93%88%E5%B8%8C%22%5D%0A%20%20ALG%20--%3E%20INST%5B%22%E5%AE%9E%E4%BE%8B%22%5D%0A%20%20HC%5B%22%E5%81%A5%E5%BA%B7%E6%A3%80%E6%9F%A5%22%5D%20--%3E%20ALG%0A%20%20AFF%5B%22%E4%BA%B2%E5%92%8C%22%5D%20--%3E%20HASH%5B%22%E4%B8%80%E8%87%B4%E6%80%A7%E5%93%88%E5%B8%8C%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>不要把全局最少连接做成中心瓶颈；P2C 用局部采样。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>羊群：所有 LB 看见同一「最闲」实例，一起打过去——信息延迟造成振荡。P2C 与随机化减轻羊群。与熔断：摘除病实例后，剩余者限流要收紧，否则转移风暴。</p><p>本课不写 Maglev、GSLB 全部。也不写 CPU 调度 CFS。</p><p>亲和与均衡冲突：粘得越死越不均，越均越破 RYW 与缓存。产品选点要显式。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把服务网格 sidecar 当新算法。后课默认：无状态用 P2C 或加权随机；有状态用哈希并接受再均衡代价；一致性读要打主或带读索引的副本，不能只打「最闲从库」。追踪下一课给每次挑选留下因果。</p><p>均衡器改变的是延迟分布与命中率，不改变对象是否线性一致。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>轮询/随机忽略队列；P2C 用两次采样压最长队。</li><li>哈希粘滞换缓存与会话，牺牲均衡。</li><li>健康检查误摘会制造转移风暴。</li><li>出处：Mitzenmacher 两选择；Dean and Barroso。</li></ul>',10))])}const C=s(h,[["render",_]]);export{P as __pageData,C as default};
